E("Slow cooker honey roast ham","1–1.2kg gammon; onion; apple juice; honey; mustard; brown sugar","Cook gammon with onion and apple juice until thoroughly cooked, following joint and appliance guidance. Rest, brush with honey, mustard and sugar, then glaze briefly in a hot oven or under grill.","https://www.bbcgoodfood.com/recipes/collection/slow-cooker-recipes","6–8 hours on LOW","10 minutes"),
E("Slow cooker chicken shawarma","800g chicken thighs; onion; garlic; cumin; paprika; coriander; turmeric; stock; lemon juice","Mix garlic, spices, stock and lemon. Add onion and chicken to cooker and pour over spice mixture. Cook until chicken is fully cooked, shred or slice and briefly grill for colour if desired.","https://www.bbc.com/food/collections/slow_cooker_recipes","5–6 hours on LOW","15 minutes"),
E("Slow cooker chicken and sweet potato stew","700g chicken thighs; sweet potatoes; onion; carrots; tomatoes; stock; smoked paprika; thyme","Add diced vegetables, chicken, tomatoes, stock and herbs to cooker. Cook until chicken is thoroughly cooked and sweet potato tender. Season and serve.","https://www.bbcgoodfood.com/recipes/collection/slow-cooker-recipes","5–6 hours on LOW","15 minutes"),
 )
 fun all(): List<Recipe> = e.mapIndexed { i, r ->
  Recipe(id="slowcooker-curated-${i+1}",title=r.title,
   description="A distinct slow-cooker dish. PantryPal provides a concise adaptation; open the credited source for the publisher's full recipe and compare quantities and method.",
   ingredients=r.ingredients.replace("; ", "\n"),instructions=r.steps,sourceUrl=r.source,
   prepTime=r.prep,cookTime=r.cook,servings="4")
 }
}
